// kernel/racecheck.c — Test Module
struct race_run {
    int id;                     // page ID (0, 1, or 2)
    struct race_run *next;      // link to next page
};

static struct {
    struct spinlock lock;       // XV6 spinlock
    struct race_run pages[3];   // P0, P1, P2
    struct race_run *freelist;  // shared head pointer
    struct race_run *allocated[2]; // per-worker result
} demo;

// UNLOCKED — both CPUs run this at the same time
page = __atomic_load_n(&demo.freelist, __ATOMIC_RELAXED);
next = page ? page->next : 0;
demo.observed[worker_id] = page;

rendezvous(worker_id);  // wait until BOTH CPUs have read

if (page)
    __atomic_store_n(&demo.freelist, next, __ATOMIC_RELAXED);

// SPINLOCK — mutual exclusion with XV6 spinlock
rendezvous(worker_id);    // both CPUs are ready

acquire(&demo.lock);      // only ONE CPU can proceed
page = __atomic_load_n(&demo.freelist, __ATOMIC_RELAXED);
if (page)
    __atomic_store_n(&demo.freelist, page->next, __ATOMIC_RELAXED);
release(&demo.lock);      // other CPU can now enter

// user/racetest.c — orchestrates the experiment
int main(void) {
    // Run WITHOUT lock → expect INCONSISTENT
    run_case(UNLOCKED);

    // Run WITH spinlock → expect CONSISTENT
    run_case(SPINLOCK);

    printf("XV6 RACE DEMO: PASS");
}

// Each run_case():
//   raceinit(mode)  → reset list to P0→P1→P2
//   fork() × 2      → one child per CPU
//   raceworker(id)   → each child enters kernel
//   wait() × 2      → parent waits
//   racereport()     → kernel prints audit
